-- Degree Programs - Finalization Lot 11: academic finance, competencies and portfolio. Run after 019.
do $$ begin create type public.academic_financial_account_status as enum ('ACTIVE','ON_HOLD','CLOSED','ARCHIVED');exception when duplicate_object then null;end $$;
do $$ begin create type public.academic_charge_status as enum ('DRAFT','POSTED','PARTIALLY_PAID','PAID','WAIVED','VOIDED');exception when duplicate_object then null;end $$;
do $$ begin create type public.academic_payment_status as enum ('PENDING','CONFIRMED','FAILED','REFUNDED','CANCELLED');exception when duplicate_object then null;end $$;
do $$ begin create type public.academic_competency_result as enum ('NOT_ASSESSED','DEVELOPING','ACHIEVED','MASTERED','EXEMPTED');exception when duplicate_object then null;end $$;
create sequence if not exists public.academic_account_number_seq;create sequence if not exists public.academic_charge_number_seq;create sequence if not exists public.academic_payment_number_seq;
create table if not exists public.academic_student_financial_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null unique references public.academic_students(id),account_number text not null unique,currency char(3) not null default 'XAF',status public.academic_financial_account_status not null default 'ACTIVE',hold_reason text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.academic_tuition_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),program_id uuid not null references public.academic_programs(id),academic_year_id uuid not null references public.academic_years(id),code citext not null,name_fr text not null,name_en text not null,amount numeric(14,2) not null check(amount>=0),currency char(3) not null,mandatory boolean not null default true,due_date date,status public.academic_record_status not null default 'ACTIVE',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(program_id,academic_year_id,code));
create table if not exists public.academic_student_charges(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),account_id uuid not null references public.academic_student_financial_accounts(id),tuition_item_id uuid references public.academic_tuition_items(id),registration_id uuid references public.academic_administrative_registrations(id),charge_number text not null unique,description_fr text not null,description_en text not null,amount numeric(14,2) not null check(amount>0),currency char(3) not null,due_date date,status public.academic_charge_status not null default 'POSTED',posted_by uuid not null references public.profiles(id),posted_at timestamptz not null default now(),voided_by uuid references public.profiles(id),voided_at timestamptz,void_reason text);
create table if not exists public.academic_student_payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),account_id uuid not null references public.academic_student_financial_accounts(id),payment_number text not null unique,external_payment_id text,payment_method text not null,amount numeric(14,2) not null check(amount>0),currency char(3) not null,paid_at timestamptz not null default now(),status public.academic_payment_status not null default 'PENDING',confirmed_by uuid references public.profiles(id),confirmed_at timestamptz,recorded_by uuid not null references public.profiles(id),notes text,unique(organization_id,external_payment_id));
create table if not exists public.academic_payment_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),payment_id uuid not null references public.academic_student_payments(id),charge_id uuid not null references public.academic_student_charges(id),amount numeric(14,2) not null check(amount>0),allocated_by uuid not null references public.profiles(id),allocated_at timestamptz not null default now(),unique(payment_id,charge_id));
create table if not exists public.academic_competencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),program_id uuid not null references public.academic_programs(id),code citext not null,name_fr text not null,name_en text not null,description_fr text not null,description_en text not null,competency_level text,status public.academic_record_status not null default 'ACTIVE',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(program_id,code));
create table if not exists public.academic_course_competencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),course_id uuid not null references public.academic_courses(id),competency_id uuid not null references public.academic_competencies(id),contribution_weight numeric(5,2) not null default 100 check(contribution_weight>0 and contribution_weight<=100),expected_result public.academic_competency_result not null default 'ACHIEVED',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(course_id,competency_id));
create table if not exists public.academic_student_competency_results(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),competency_id uuid not null references public.academic_competencies(id),course_id uuid references public.academic_courses(id),result public.academic_competency_result not null,evidence_text text,evidence_document_id uuid references public.academic_documents(id),assessed_by uuid not null references public.profiles(id),assessed_at timestamptz not null default now(),validated_by uuid references public.profiles(id),validated_at timestamptz,unique(student_id,competency_id,course_id));
create table if not exists public.academic_portfolio_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),item_type text not null check(item_type in('COMPETENCY','INTERNSHIP','PROJECT','THESIS','CERTIFICATE','ACHIEVEMENT','BADGE','ACADEMIC_CV','OTHER')),title_fr text not null,title_en text not null,description_fr text,description_en text,source_table text,source_id uuid,storage_path text,visibility text not null default 'PRIVATE' check(visibility in('PRIVATE','INSTITUTION','PUBLIC')),status public.academic_record_status not null default 'ACTIVE',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists academic_charges_account_idx on public.academic_student_charges(account_id,status,due_date);create index if not exists academic_payments_account_idx on public.academic_student_payments(account_id,status,paid_at desc);create index if not exists academic_competency_results_student_idx on public.academic_student_competency_results(student_id,result);create index if not exists academic_portfolio_student_idx on public.academic_portfolio_items(student_id,status,item_type);
create or replace function public.academic_set_finance_numbers()returns trigger language plpgsql set search_path=public as $$begin if tg_table_name='academic_student_financial_accounts'and new.account_number is null then new.account_number='AFA-'||lpad(nextval('academic_account_number_seq')::text,8,'0');elsif tg_table_name='academic_student_charges'and new.charge_number is null then new.charge_number='ACH-'||lpad(nextval('academic_charge_number_seq')::text,8,'0');elsif tg_table_name='academic_student_payments'and new.payment_number is null then new.payment_number='APY-'||lpad(nextval('academic_payment_number_seq')::text,8,'0');end if;return new;end$$;
do $$declare t text;begin foreach t in array array['academic_student_financial_accounts','academic_student_charges','academic_student_payments']loop execute format('drop trigger if exists %I_numbers on public.%I',t,t);execute format('create trigger %I_numbers before insert on public.%I for each row execute function public.academic_set_finance_numbers()',t,t);end loop;end$$;
create or replace function public.academic_guard_payment_allocation()returns trigger language plpgsql set search_path=public as $$declare p record;c record;allocated numeric;begin select * into p from public.academic_student_payments where id=new.payment_id;select * into c from public.academic_student_charges where id=new.charge_id;if p.account_id<>c.account_id or p.currency<>c.currency or p.status<>'CONFIRMED'then raise exception 'Payment and charge account/currency/status mismatch';end if;select coalesce(sum(amount),0)into allocated from public.academic_payment_allocations where payment_id=p.id and id<>coalesce(new.id,gen_random_uuid());if allocated+new.amount>p.amount then raise exception 'Payment over-allocation forbidden';end if;select coalesce(sum(amount),0)into allocated from public.academic_payment_allocations where charge_id=c.id and id<>coalesce(new.id,gen_random_uuid());if allocated+new.amount>c.amount then raise exception 'Charge over-allocation forbidden';end if;return new;end$$;
drop trigger if exists academic_payment_allocation_guard on public.academic_payment_allocations;create trigger academic_payment_allocation_guard before insert or update on public.academic_payment_allocations for each row execute function public.academic_guard_payment_allocation();
create or replace view public.academic_student_financial_balances_v with(security_invoker=true)as select a.organization_id,a.id account_id,a.student_id,a.account_number,a.currency,a.status,coalesce((select sum(c.amount)from public.academic_student_charges c where c.account_id=a.id and c.status not in('VOIDED','WAIVED')),0)charges,coalesce((select sum(pa.amount)from public.academic_payment_allocations pa join public.academic_student_payments p on p.id=pa.payment_id where p.account_id=a.id and p.status='CONFIRMED'),0)allocated,coalesce((select sum(c.amount)from public.academic_student_charges c where c.account_id=a.id and c.status not in('VOIDED','WAIVED')),0)-coalesce((select sum(pa.amount)from public.academic_payment_allocations pa join public.academic_student_payments p on p.id=pa.payment_id where p.account_id=a.id and p.status='CONFIRMED'),0)balance from public.academic_student_financial_accounts a;
insert into public.academic_role_permissions(role,permission_code,description_fr,description_en)values('STUDENT','finance.self.read','Consulter sa situation financiere','Read own financial account'),('STUDENT','competency.self.read','Consulter ses competences','Read own competencies'),('STUDENT','portfolio.self.manage','Gerer son portfolio','Manage own portfolio'),('FINANCE_OFFICER','academic.finance.read','Consulter les finances academiques','Read academic finance'),('FINANCE_OFFICER','academic.finance.manage','Gerer les finances academiques','Manage academic finance'),('PROGRAM_COORDINATOR','competency.read','Consulter les competences','Read competencies'),('PROGRAM_COORDINATOR','competency.manage','Gerer les competences','Manage competencies'),('ACADEMIC_ADMIN','academic.finance.read','Consulter les finances academiques','Read academic finance'),('ACADEMIC_ADMIN','academic.finance.manage','Gerer les finances academiques','Manage academic finance'),('ACADEMIC_ADMIN','competency.read','Consulter les competences','Read competencies'),('ACADEMIC_ADMIN','competency.manage','Gerer les competences','Manage competencies'),('SUPER_ADMIN','academic.finance.read','Consulter les finances academiques','Read academic finance'),('SUPER_ADMIN','academic.finance.manage','Gerer les finances academiques','Manage academic finance'),('SUPER_ADMIN','competency.read','Consulter les competences','Read competencies'),('SUPER_ADMIN','competency.manage','Gerer les competences','Manage competencies')on conflict(role,permission_code)do update set description_fr=excluded.description_fr,description_en=excluded.description_en;
do $$declare t text;begin foreach t in array array['academic_student_financial_accounts','academic_tuition_items','academic_student_charges','academic_student_payments','academic_payment_allocations','academic_competencies','academic_course_competencies','academic_student_competency_results','academic_portfolio_items']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
drop policy if exists "financial accounts read" on public.academic_student_financial_accounts;create policy "financial accounts read" on public.academic_student_financial_accounts for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_student_financial_accounts.organization_id,'academic.finance.read'))));
drop policy if exists "financial accounts manage" on public.academic_student_financial_accounts;create policy "financial accounts manage" on public.academic_student_financial_accounts for all to authenticated using(public.academic_has_permission(organization_id,'academic.finance.manage'))with check(public.academic_has_permission(organization_id,'academic.finance.manage'));
drop policy if exists "tuition items read" on public.academic_tuition_items;create policy "tuition items read" on public.academic_tuition_items for select to authenticated using(public.academic_has_access(organization_id));
drop policy if exists "tuition items manage" on public.academic_tuition_items;create policy "tuition items manage" on public.academic_tuition_items for all to authenticated using(public.academic_has_permission(organization_id,'academic.finance.manage'))with check(public.academic_has_permission(organization_id,'academic.finance.manage'));
drop policy if exists "charges read" on public.academic_student_charges;create policy "charges read" on public.academic_student_charges for select to authenticated using(exists(select 1 from public.academic_student_financial_accounts a join public.academic_students s on s.id=a.student_id where a.id=account_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_student_charges.organization_id,'academic.finance.read'))));
drop policy if exists "charges manage" on public.academic_student_charges;create policy "charges manage" on public.academic_student_charges for all to authenticated using(public.academic_has_permission(organization_id,'academic.finance.manage'))with check(public.academic_has_permission(organization_id,'academic.finance.manage'));
drop policy if exists "payments read" on public.academic_student_payments;create policy "payments read" on public.academic_student_payments for select to authenticated using(exists(select 1 from public.academic_student_financial_accounts a join public.academic_students s on s.id=a.student_id where a.id=account_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_student_payments.organization_id,'academic.finance.read'))));
drop policy if exists "payments manage" on public.academic_student_payments;create policy "payments manage" on public.academic_student_payments for all to authenticated using(public.academic_has_permission(organization_id,'academic.finance.manage'))with check(public.academic_has_permission(organization_id,'academic.finance.manage'));
drop policy if exists "allocations read" on public.academic_payment_allocations;create policy "allocations read" on public.academic_payment_allocations for select to authenticated using(exists(select 1 from public.academic_student_payments p join public.academic_student_financial_accounts a on a.id=p.account_id join public.academic_students s on s.id=a.student_id where p.id=payment_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_payment_allocations.organization_id,'academic.finance.read'))));
drop policy if exists "allocations manage" on public.academic_payment_allocations;create policy "allocations manage" on public.academic_payment_allocations for all to authenticated using(public.academic_has_permission(organization_id,'academic.finance.manage'))with check(public.academic_has_permission(organization_id,'academic.finance.manage'));
drop policy if exists "competencies read" on public.academic_competencies;create policy "competencies read" on public.academic_competencies for select to authenticated using(public.academic_has_access(organization_id));
drop policy if exists "competencies manage" on public.academic_competencies;create policy "competencies manage" on public.academic_competencies for all to authenticated using(public.academic_has_permission(organization_id,'competency.manage'))with check(public.academic_has_permission(organization_id,'competency.manage'));
drop policy if exists "course competencies read" on public.academic_course_competencies;create policy "course competencies read" on public.academic_course_competencies for select to authenticated using(public.academic_has_access(organization_id));
drop policy if exists "competency results read" on public.academic_student_competency_results;create policy "competency results read" on public.academic_student_competency_results for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_student_competency_results.organization_id,'competency.read'))));
drop policy if exists "portfolio read" on public.academic_portfolio_items;create policy "portfolio read" on public.academic_portfolio_items for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_permission(academic_portfolio_items.organization_id,'student.read'))));
drop policy if exists "portfolio self manage" on public.academic_portfolio_items;create policy "portfolio self manage" on public.academic_portfolio_items for all to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()))with check(created_by=auth.uid()and exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
revoke all on function public.academic_set_finance_numbers(),public.academic_guard_payment_allocation()from public;
